botster.register{
  handlers = {{ kind = "mcp_tool", id = "h_t", name = "t", description = "d", input_schema = { type = "object" },
    call = function(payload, request)

      local e = botster.base64.encode{ bytes = "hi" }
      local d = botster.base64.decode{ text = e.value }
      local j = botster.json.encode{ value = { a = 1 } }
      local jd = botster.json.decode{ text = j.value }
      local jn = botster.json.decode{ text = "null" }
      local jl = botster.json.decode{ text = "[1,2]" }
      local h = botster.crypto.sha256{ bytes_b64 = e.value }
      return {
        b64_is_string = type(e.value) == "string",
        b64_round_trip = d.value,
        json_text_is_string = type(j.value) == "string",
        json_round_trip = jd.value.a,
        json_null_is_sentinel = jn.value == botster.json.null,
        json_list_len = #jl.value,
        all_enveloped = e.ok == true and d.ok == true and j.ok == true and jd.ok == true and jn.ok == true and jl.ok == true,
        digest_is_string = type(h.value.digest_b64) == "string",
      }
    end }},
}
